# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">SIMPLE PAST TENSE: NEGATIVE &amp; INTERROGATIVE FORMS (OLUMSUZ VE SORU)</text>\n  <rect x="25" y="48" width="210" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="130" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Affirmative (+)</text>\n  <text x="40" y="98" font-size="11.5" font-weight="bold" fill="#1e40af">Subject + V2 (Past Form)</text>\n  <text x="40" y="122" font-size="11" fill="#334155">• Regular: -ed / -d / -ied</text>\n  <text x="48" y="140" font-size="10.5" fill="#475569">moved, graduated, studied</text>\n  <text x="40" y="164" font-size="11" fill="#334155">• Irregular: Special V2 form</text>\n  <text x="48" y="182" font-size="10.5" fill="#475569">went, won, wrote, became</text>\n  <text x="40" y="210" font-size="11" font-weight="bold" fill="#1d4ed8">Ex: She won a prize in 1911.</text>\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#fef2f2" stroke="#ef4444"/>\n  <text x="350" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">Negative (-)</text>\n  <text x="260" y="98" font-size="11.5" font-weight="bold" fill="#991b1b">Subject + didn&apos;t + V1 (Base)</text>\n  <text x="260" y="124" font-size="11" fill="#334155">• Yardımcı fiil: did not (didn&apos;t)</text>\n  <text x="260" y="146" font-size="11" font-weight="bold" fill="#b91c1c">• Fiil 1. haline (V1) döner!</text>\n  <text x="260" y="172" font-size="10.5" fill="#334155">He didn&apos;t get married.</text>\n  <text x="260" y="190" font-size="10.5" fill="#334155">They didn&apos;t move to Paris.</text>\n  <text x="260" y="215" font-size="10.5" font-weight="bold" fill="#991b1b">(was not / were not + noun/adj)</text>\n  <rect x="465" y="48" width="210" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="570" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Interrogative (?)</text>\n  <text x="480" y="98" font-size="11.5" font-weight="bold" fill="#166534">(Wh-) + Did + Subj + V1?</text>\n  <text x="480" y="124" font-size="11" fill="#334155">• Did he invent the lightbulb?</text>\n  <text x="488" y="142" font-size="10.5" fill="#475569">Yes, he did. / No, he didn&apos;t.</text>\n  <text x="480" y="168" font-size="11" fill="#334155">• Why did she move to London?</text>\n  <text x="488" y="186" font-size="10.5" fill="#475569">— To study physics at university.</text>\n  <text x="480" y="215" font-size="10.5" font-weight="bold" fill="#15803d">• Where / When WAS he born?</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">KEY IRREGULAR VERBS IN BIOGRAPHIES (DÜZENSİZ FİİLLER V1 → V2)</text>\n  <rect x="30" y="50" width="310" height="185" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="185" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Life &amp; Career Irregular Verbs</text>\n  <text x="48" y="102" font-size="11.5" fill="#334155">• grow up → <tspan font-weight="bold" fill="#1e40af">grew up</tspan> (büyümek, yetişmek)</text>\n  <text x="48" y="126" font-size="11.5" fill="#334155">• become → <tspan font-weight="bold" fill="#1e40af">became</tspan> (olmak)</text>\n  <text x="48" y="150" font-size="11.5" fill="#334155">• get married → <tspan font-weight="bold" fill="#1e40af">got married</tspan> (evlenmek)</text>\n  <text x="48" y="174" font-size="11.5" fill="#334155">• have / has → <tspan font-weight="bold" fill="#1e40af">had</tspan> (sahip olmak)</text>\n  <text x="48" y="198" font-size="11.5" fill="#334155">• leave → <tspan font-weight="bold" fill="#1e40af">left</tspan> (ayrılmak, bırakmak)</text>\n  <text x="48" y="222" font-size="11.5" fill="#334155">• spend → <tspan font-weight="bold" fill="#1e40af">spent</tspan> (vakit/para geçirmek)</text>\n  <rect x="360" y="50" width="310" height="185" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="515" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Achievement &amp; Science Irregular Verbs</text>\n  <text x="378" y="102" font-size="11.5" fill="#334155">• win → <tspan font-weight="bold" fill="#92400e">won</tspan> (kazanmak: won an award/prize)</text>\n  <text x="378" y="126" font-size="11.5" fill="#334155">• write → <tspan font-weight="bold" fill="#92400e">wrote</tspan> (yazmak: wrote books)</text>\n  <text x="378" y="150" font-size="11.5" fill="#334155">• make → <tspan font-weight="bold" fill="#92400e">made</tspan> (yapmak: made inventions)</text>\n  <text x="378" y="174" font-size="11.5" fill="#334155">• find → <tspan font-weight="bold" fill="#92400e">found</tspan> (bulmak, keşfetmek)</text>\n  <text x="378" y="198" font-size="11.5" fill="#334155">• begin → <tspan font-weight="bold" fill="#92400e">began</tspan> (başlamak)</text>\n  <text x="378" y="222" font-size="11.5" fill="#334155">• go → <tspan font-weight="bold" fill="#92400e">went</tspan> (gitmek) / take → <tspan font-weight="bold" fill="#92400e">took</tspan> (almak)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">FAMOUS BIOGRAPHIES &amp; CHRONOLOGICAL MILESTONES</text>\n  <rect x="25" y="50" width="205" height="185" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="127" y="74" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">Mustafa Kemal Atatürk</text>\n  <text x="38" y="100" font-size="11" fill="#334155">• Born in Salonika in 1881.</text>\n  <text x="38" y="122" font-size="11" fill="#334155">• Graduated from the Military</text>\n  <text x="46" y="138" font-size="11" fill="#334155">Academy in 1905.</text>\n  <text x="38" y="160" font-size="11" fill="#334155">• Founded the Republic of</text>\n  <text x="46" y="176" font-size="11" fill="#334155">Türkiye on 29th October 1923.</text>\n  <text x="38" y="202" font-size="11" font-weight="bold" fill="#1e40af">• Died on 10th November 1938.</text>\n  <rect x="247" y="50" width="205" height="185" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="350" y="74" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">Aziz Sancar (Scientist)</text>\n  <text x="260" y="100" font-size="11" fill="#334155">• Born in Savur, Mardin in 1946.</text>\n  <text x="260" y="122" font-size="11" fill="#334155">• Grew up in a large family.</text>\n  <text x="260" y="144" font-size="11" fill="#334155">• Graduated from Istanbul</text>\n  <text x="268" y="160" font-size="11" fill="#334155">University Faculty of Medicine.</text>\n  <text x="260" y="182" font-size="11" fill="#334155">• Moved to the USA for research.</text>\n  <text x="260" y="206" font-size="11" font-weight="bold" fill="#166534">• Won the Nobel Prize in 2015.</text>\n  <rect x="470" y="50" width="205" height="185" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="572" y="74" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#a16207">Marie Curie (Physicist)</text>\n  <text x="483" y="100" font-size="11" fill="#334155">• Born in Warsaw in 1867.</text>\n  <text x="483" y="122" font-size="11" fill="#334155">• Moved to Paris to study</text>\n  <text x="491" y="138" font-size="11" fill="#334155">physics and mathematics.</text>\n  <text x="483" y="160" font-size="11" fill="#334155">• Discovered radium &amp; polonium.</text>\n  <text x="483" y="182" font-size="11" fill="#334155">• First woman to win a Nobel</text>\n  <text x="491" y="198" font-size="11" font-weight="bold" fill="#b45309">Prize (in 1903 and 1911).</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
